    zone.setAttribute("readonly", "readonly");
    zone.style.position = "fixed";
    zone.style.top = "-1000px";
    document.body.append(zone);
    zone.select();
    const ok = document.execCommand ? document.execCommand("copy") : false;
    zone.remove();
    return !!ok;
  } catch (e) { return false; }
}

